"""作业 9：策略梯度与 Actor-Critic；独立解答，非官方答案。"""
def get_questions(p, f, ul):
    return [
    (9,1,'基于策略的方法优化什么','基于策略的强化学习直接优化',['状态价值函数','动作价值函数','策略函数','优势价值函数'],2,
    p('答案为 C。Policy-based RL 显式表示策略 πθ(a|s) 或确定性策略 μθ(s)，直接调整策略参数 θ，以提高期望回报。价值与优势可以帮助估计更新方向，但不是该问题中直接优化的策略对象。') + f('θ* ∈ arg max<sub>θ</sub> J(θ)，J(θ)=E<sub>τ∼πθ</sub>[R(τ)]'),
    '策略与价值方法的区别',p('价值方法主要学习 Q 或 V，再从价值导出动作选择；策略方法直接优化动作选择规则。Actor-Critic 同时学习策略与价值，属于结合两者的框架。')),
    (9,2,'随机策略不是必需条件','下列关于 policy-based RL 的说法中，错误的有',['可以学习随机策略','适用于连续动作空间','本质上是一个优化问题','必须学习得到随机策略'],3,
    p('答案为 D。基于策略的方法可以学习随机策略，也可以学习确定性策略。直接输出动作或动作分布参数，使它适合连续动作控制；目标仍是优化策略的期望表现。题干写“有”，截图为单选控件，四项中 D 为预期错误项。'),
    '随机策略与确定性策略',f('随机：a ∼ πθ(·|s)<br>确定性：a = μθ(s)') + p('随机策略可通过采样探索，确定性策略也可另加噪声探索。确定性策略梯度是基于策略方法的一类，不应把 policy-based 等同于必须随机。')),
    (9,3,'策略优化的目标','在 policy-based RL 中，主要的目标是什么',['最大化累计奖励','最小化损失函数','寻找最优价值函数','无法确定'],0,
    p('答案为 A。更准确地说，是最大化策略的期望累积回报，可以包含折扣。一次轨迹的高回报可能来自偶然性，学习目标针对的是期望表现。') + f('J(θ)=E<sub>πθ</sub>[∑<sub>t=0</sub><sup>T−1</sup> γ<sup>t</sup>R<sub>t+1</sub>]'),
    '损失函数是实现方式',p('代码里常最小化负的策略目标或代理损失，这与最大化回报不矛盾。选 B 只描述一种优化器接口，不能代替强化学习的实质目标。价值函数是辅助评估工具，而不是必须单独求解的最终目标。')),
    (9,4,'最大化目标的更新方向','在 policy-based RL 中，通常使用哪种算法来最大化策略的预期回报',['梯度上升法','共轭梯度法','拟牛顿法','启发式优化方法'],0,
    p('答案为 A。经典策略梯度沿期望回报的梯度方向上升：') + f('θ ← θ + αĝ，ĝ ≈ ∇<sub>θ</sub>J(θ)') + p('若代码最小化 L=−J，则对 L 做梯度下降即可。共轭梯度、拟牛顿或启发式方法可以用于某些优化环节，但不是本题所问的基本策略梯度更新。'),
    '上升不保证每次采样更新都提高回报',p('梯度是估计值，目标也可能非凸；步长过大或估计噪声较大时，单次更新可能退步。TRPO 等方法进一步约束策略变化，以控制过大的更新。')),
    (9,5,'基线是否改变策略梯度','减去一个基线会____策略梯度的值',['增大','减小','不影响','不确定'],2,
    '<p class="note">建议 C，指减去合适的、给定状态下不依赖动作的基线，不改变期望策略梯度。单个样本梯度及有限批次估计可以改变，方差也可能改变。</p>' +
    f('E<sub>a∼πθ</sub>[b(s)∇<sub>θ</sub>log πθ(a|s)]<br>= b(s)∑<sub>a</sub>∇<sub>θ</sub>πθ(a|s) = b(s)∇<sub>θ</sub>1 = 0') +
    p('因此把回报或动作价值减去 b(s)，在通常可交换求导与期望的条件下，期望更新方向不变。常用 b(s)=Vπ(s)，得到优势形式。'),
    '基线条件与停止梯度',p('任意依赖动作的项不能不加修正地当作基线减去。实现 actor 更新时，基线或优势通常作为不求导的权重；即使共享参数，也不能误把基线的导数加入原本的策略梯度公式。基线选得差时未必降低方差。')),
    (9,6,'Critic 的作用','Actor-Critic 中 critic 的作用是什么',['选择最优行动','估计当前状态价值','估计转移概率','输出策略梯度'],1,
    p('答案为 B，按常见状态价值 critic 理解。Critic 评估当前策略的价值，并为 actor 提供优势或 TD 误差信号；actor 负责策略和动作选择。') + f('δₜ = Rₜ₊₁ + γV<sub>w</sub>(Sₜ₊₁) − V<sub>w</sub>(Sₜ)'),
    'Critic 不只限于 V(s)',p('不同 Actor-Critic 算法的 critic 可以估计 V(s)、Q(s,a) 或其他价值量。它不是环境转移模型；即使某些算法通过 Q 对动作求导来训练 actor，critic 的主要学习对象仍是价值，而非直接输出完整策略梯度。')),
    (9,7,'重参数化的方差','重参数化技巧相较于 REINFORCE 具有____的方差',['更大','更小','同样','不确定'],1,
    '<p class="note">按常见课程比较选 B：在适用的连续、可微问题中，路径梯度通常比朴素 REINFORCE 方差更小。这不是对所有分布、目标函数和控制变量组合都成立的定理。</p>' +
    p('重参数化把随机动作写成参数化变换和外部噪声：') + f('a = μθ(s) + σθ(s)ε，ε ∼ N(0,1)') + p('这样可通过动作到可微目标的路径使用链式法则；REINFORCE 则使用目标值乘以 ∇θ log πθ(a|s) 的得分函数估计。'),
    '适用条件与通用性',p('路径梯度需要可微的采样变换和后续目标。黑箱不可微环境的完整回报通常不能直接穿过环境求导；可使用可微 critic 或模型，但会引入相应估计问题。REINFORCE 不要求环境可微，也可用于离散动作。参考：<a href="https://proceedings.mlr.press/v80/jankowiak18a.html">Pathwise Derivatives Beyond the Reparameterization Trick</a>。')),
    (9,8,'Actor 与 Critic 的对应关系','Actor-Critic 算法中的 Actor 和 Critic 分别指代什么',['Actor 指代策略，Critic 指代价值函数','Actor 指代价值函数，Critic 指代策略','Actor 和 Critic 都指代策略','Actor 和 Critic 都指代价值函数'],0,
    p('答案为 A。Actor 学习怎样行动，Critic 学习当前行动方式的长期效果。两者分别承担策略优化与价值评估的任务。') + f('Actor πθ → 与环境交互 → 经验 → Critic Vw 或 Qw<br>Critic 的评价信号 → 改进 Actor'),
    '与 REINFORCE 的联系',p('经典 REINFORCE 用完整回报权重更新策略；Actor-Critic 利用学习到的价值估计辅助更新，通常可进行自举和更及时的学习，但要考虑 critic 误差带来的偏差。并非所有带基线的 REINFORCE 都应不加区分地称为自举型 Actor-Critic。')),
    (9,9,'识别非策略方法','以下哪个算法不是 Policy-based RL 算法',['REINFORCE','Q-learning','Actor-Critic','Trust Region Policy Optimization (TRPO)'],1,
    p('答案为 B。Q-learning 是基于价值的方法，学习 Q 后导出贪心或带探索的策略。REINFORCE 与 TRPO 直接优化策略，Actor-Critic 则包含直接学习策略的 actor。'),
    '分类维度不要混淆',p('Policy-based 与 value-based 关注直接学习的对象；on-policy 与 off-policy 关注数据策略和目标策略；model-based 与 model-free 关注是否依赖环境模型。这些分类不是同一个维度。')),
    (9,10,'降低策略梯度方差','在 policy-based RL 中，哪个技巧可以防止策略梯度算法的方差过大',['添加基线','使用重要性采样','使用 LSTM 网络','增加训练数据'],0,
    p('预期答案为 A。使用合适基线是专门针对策略梯度估计的经典降方差技巧，不改变期望梯度。') + p('重要性采样用于分布校正，可能使方差变大；LSTM 处理历史信息，不是直接的降方差保证。增加独立样本的批量平均也能降低估计方差，但本题所指的标准技巧是基线。'),
    '基线与批量平均的区别',p('基线改变单个样本估计的波动；增加样本数通过平均降低估计噪声。若样本独立且同分布，均值的方差为单样本方差除以样本数；相关轨迹不满足这一简单等式。也不能保证任意基线都优于不加基线。')),
    (9,11,'重要性采样的性质','下列关于重要性采样的说法中，哪些是正确的',
    ['不改变数据的方差','可以用来估计不同分布下的期望值','采样分布必须保证在被估计的分布概率密度非 0 处非 0','乘重要性权重之后的数据服从被估计的分布'],(1,2),
    '<p class="note">严格按原句选 B、C。D 若只是“加权后可计算目标期望”的口语简写，有时会被教学材料视为正确；但它并不意味着原始样本或乘权后的数值自动服从目标分布。</p>' +
    f('X ∼ q，w(x)=p(x)/q(x)<br>E<sub>p</sub>[f(X)] = E<sub>q</sub>[w(X)f(X)]') +
    ul('A 不选：权重改变估计量的波动；重要性采样可能增大或降低方差。原始 X 的采样分布仍是 q，不能据此说加权估计的方差不变。','B 正确：用 q 的样本估计 p 下的期望。','C 正确：一般要求 p 相对于 q 绝对连续，即 p 有概率质量的地方 q 也要能覆盖；还需适当可积性。','D 严格说不正确：加权改变的是样本对估计的贡献，不是直接变换原始样本的分布。') +
    p('例：目标 p(0)=0.8、p(1)=0.2，采样 q(0)=q(1)=0.5，权重分别 1.6、0.4。用权重求 Eₚ[X] 得 0.5×1.6×0 + 0.5×0.4×1 = 0.2；但乘权数值 w(X)X 只可能取 0 或 0.4，显然不等于目标在 {0,1} 上的分布。'),
    '加权分布与重采样',p('形式上 w(x)q(x)=p(x)，因此加权测度对应目标分布；有限样本的加权经验分布只是近似。若再按归一化权重重采样，可以近似生成目标分布样本，但这是额外步骤。自归一化估计 ∑wᵢfᵢ/∑wᵢ 一般有有限样本偏差，不能与普通无偏 IS 混为一谈。')),
    (9,12,'REINFORCE 的学习信号','REINFORCE 算法基于什么计算策略梯度',['TD 目标','累积回报','动作价值函数','状态价值函数'],1,
    p('答案为 B。经典 REINFORCE 从完整回合采集回报，再用该回报加权所选动作的对数概率梯度。') + f('无折扣有限回合示意：<br>ĝ = ∑<sub>t=0</sub><sup>T−1</sup> ∇θ log πθ(Aₜ|Sₜ)Gₜ') + p('理论策略梯度可写为 Qπ 的期望，REINFORCE 使用采样回报估计这一学习信号，而非必须训练一个 Q 网络。TD 目标对应自举方法，不是经典 REINFORCE 的完整回报目标。'),
    '折扣约定要一致',p('上式为 γ=1 的有限回合示意。若优化从初始时刻计算的折扣目标 J=E[∑γᵗRₜ₊₁]，且 Gₜ 从时刻 t 重新计折扣，则相应无偏轨迹梯度带有 γᵗ 权重。不同教材可能使用折扣状态访问分布吸收该权重，不能混用约定。')),
    (9,13,'策略梯度估计相关技巧','以下哪些技巧用于估计策略梯度',['REINFORCE','重参数化','添加基线','重要性采样'],(0,1,3),
    p('正确答案为 A、B、D，依据用户提供的课程答案修正。本题区分策略梯度估计方法与辅助降低方差的技巧，C 不选。') + ul('<b>A. REINFORCE：</b>用得分函数 / 似然比形式，将对数策略概率的梯度与回报相乘，构造策略梯度估计。','<b>B. 重参数化：</b>将随机采样写成参数化变换与外部噪声，在可微条件下通过链式法则构造路径梯度。','<b>C. 添加基线：</b>用于调整已有梯度估计的方差，不是本题所列的梯度估计方法，因此不选。合适的不依赖动作的基线不改变期望策略梯度。','<b>D. 重要性采样：</b>用目标分布与采样分布的概率比校正期望，从其他策略或分布产生的数据估计目标策略梯度。'),
    '为什么第 10 题选基线，本题不选？',p('第 10 题问的是降低方差，合适基线正是经典技巧；本题按课程答案问梯度估计方法，选 REINFORCE、重参数化和重要性采样。两题考查侧重点不同。') + p('基线可以与 REINFORCE 等方法结合，但不单独提供完整的梯度估计机制。重要性采样在本题归入估计方法，其具体作用是分布校正，也需要结合梯度表达使用，并不保证降低方差。')),
    (9,14,'有限差分是否要求可导','有限差分方法需要目标函数可导',['对','错'],1,
    '<p class="note">按“使用有限差分优化是否需要可导目标或解析梯度”的课程语境，选 B，错。仅计算差分商只需要目标函数值；若声称差分极限等于真实导数，则仍需相应可导性。</p>' +
    f('中心差分：∂J/∂θᵢ ≈ [J(θ+h eᵢ) − J(θ−h eᵢ)]/(2h)') +
    p('有限差分可以用于黑箱函数，不需要反向传播或解析导数。即便在不可导点也能计算有限 h 的差分商，但它不一定代表真实梯度；例如 J(x)=|x| 在 0 处中心差分为 0，而导数不存在。'),
    '步长与采样噪声',p('h 太大使近似误差增加，太小会放大数值误差和随机回报噪声。逐坐标中心差分通常需要约 2d 次函数评估，高维策略参数下代价很大；可通过多次评估或共用随机数降低比较噪声。')),
    ]

RECAP = '''<section id="pg-recap"><div class="eyebrow">POLICY GRADIENT / 复习卡</div><h2>分清优化目标、估计方法与校正技巧</h2><table><caption>策略学习知识对照</caption><thead><tr><th>概念</th><th>要点</th><th>边界条件</th></tr></thead><tbody><tr><td>Policy-based RL</td><td>直接优化策略的期望回报</td><td>可学习随机或确定性策略</td></tr><tr><td>REINFORCE</td><td>对数概率梯度乘完整回报</td><td>不要求环境可微，通常方差较大</td></tr><tr><td>基线</td><td>合适基线不改变期望梯度</td><td>不能把单个样本变化与期望混淆</td></tr><tr><td>重参数化</td><td>通过采样变换求路径梯度</td><td>需要可微路径；较低方差不是普遍定理</td></tr><tr><td>重要性采样</td><td>校正不同分布下的期望</td><td>覆盖条件、可积性与权重方差</td></tr><tr><td>Actor-Critic</td><td>Actor 学策略，Critic 学价值</td><td>Critic 可用 V 或 Q 等形式</td></tr><tr><td>有限差分</td><td>用函数值差估计变化</td><td>计算差分不要求解析梯度；逼近导数需要条件</td></tr></tbody></table><p>题目来自用户提供的五张截图，共 14 题，第 11、13 题为多选。除第 13 题已按用户提供的课程正确答案修正为 A、B、D 外，其余答案与解析为独立解答。第 5 题解释为期望梯度；第 7 题采用通常方差比较；第 11 题 D 按严格字面不选并解释加权测度的另一种理解；第 14 题区分可计算差分与可逼近真实导数。</p><p>参考：<a href="https://spinningup.openai.com/en/latest/spinningup/rl_intro3.html">策略梯度推导与基线</a>；<a href="https://spinningup.openai.com/en/latest/algorithms/vpg.html">Vanilla Policy Gradient</a>；<a href="https://proceedings.mlr.press/v80/jankowiak18a.html">路径梯度与重参数化</a>；<a href="https://www.incompleteideas.net/book/bookdraft2018mar21.pdf">Sutton &amp; Barto，第 5 章重要性采样、第 13 章策略梯度</a>。</p></section>'''
